SELECT p.id AS pid, e.symbol, DATE_FORMAT(e.observed_at, '%Y-%m-%d %H:%i') AS minute_utc, COUNT(*) AS n, MIN(e.price) AS min_px, MAX(e.price) AS max_px, SUM(e.delivery_status IN ('LEGACY','APPLIED')) AS accepted_n, GROUP_CONCAT(DISTINCT e.delivery_status) AS statuses, GROUP_CONCAT(DISTINCT e.source) AS sources FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event e ON e.symbol = p.symbol AND e.observed_at BETWEEN p.opened_at - INTERVAL 2 MINUTE AND p.closed_at + INTERVAL 2 MINUTE WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id, e.symbol, minute_utc ORDER BY p.id, minute_utc LIMIT 400;